/** True when the canvas font can draw this character. */
export function isSupportedGlyph(ch: string): boolean {
  return SUPPORTED_GLYPHS.has(ch);
}

/**
 * Curated agent-facing pixel-art palette. Every char here is in the
 * font; the full repertoire is SUPPORTED_GLYPHS (all printable ASCII
 * plus the symbols below).
 */
export const PALETTE = "█▓▒░·●◆✦◉+×/\\|()[]oO#@<>❄♥♦♣♠▲▼◀▶✚♪♫";

/**
 * Drop characters the canvas font cannot draw from a text string, and
 * map a UTF-16 caret position through the filtering so the input field
 * and the grid never disagree about what was typed.
 */
export function toSupportedText(
  text: string,
  caret: number,
): { text: string; caret: number } {
  let out = '';
  let newCaret = 0;
  let i = 0;
  for (const ch of text) {
    if (isSupportedGlyph(ch)) {
      out += ch;
      if (i + ch.length <= caret) newCaret += ch.length;
    }
    i += ch.length;
  }
  return { text: out, caret: newCaret };
}

/** All printable ASCII (U+0020-U+007E) — the font draws every one. */
export const ASCII_GLYPHS = " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~";

