/** Human name for a brush glyph (for tooltips / aria labels). */
export function glyphName(ch: string): string {
  const sym = SYMBOL_GLYPHS.find((s) => s.ch === ch);
  if (sym) return sym.name;
  if (ch === ' ') return 'space';
  return ch;
}

/**
 * Search the brush glyph repertoire. An empty query returns everything
 * (symbols first, then ASCII). Otherwise matches the character itself
 * or a case-insensitive substring of its name — e.g. "heart", "arrow",
 * ">".
 */
export function searchGlyphs(query: string): SymbolGlyph[] {
  const q = query.trim().toLowerCase();
  const ascii: SymbolGlyph[] = [...ASCII_GLYPHS].map((ch) => ({
    ch,
    name: ch === ' ' ? 'space' : ch,
  }));
  if (!q) return [...SYMBOL_GLYPHS, ...ascii];
  const raw = query.trim();
  const match = (g: SymbolGlyph) =>
    g.ch === raw || g.name.toLowerCase().includes(q);
  const hits = [...SYMBOL_GLYPHS, ...ascii].filter(match);
  // Exact character matches first (typing ">" should find ">").
  hits.sort((a, b) => (b.ch === raw ? 1 : 0) - (a.ch === raw ? 1 : 0));
  return hits;
}
